'use strict';
const EventEmitter = require('events').EventEmitter;

const { breakerState, events } = require('./Enums');
const defaultOpts = require('./defaultOpts');
const { TimeoutError, CircuitBrokenError } = require('./Utils');
const Stats = require('./Stats');
const globalStats = require('./globalStats');
const NonBreakingError = require('./NonBreakingError');

class Brakes extends EventEmitter {
  constructor(
    func,
    {
      name = defaultOpts.name,
      group = defaultOpts.group,
      failureThreshold = defaultOpts.failureThreshold,
      successThreshold = defaultOpts.successThreshold,
      interval = defaultOpts.interval,
      increment = defaultOpts.increment,
      exponentInterval = defaultOpts.exponentInterval,
      timeout = defaultOpts.timeout,
      fallback = defaultOpts.fallback,
      bucketSpan = defaultOpts.bucketSpan,
      bucketCount = defaultOpts.bucketCount,
      statsInterval = defaultOpts.statsInterval,
      registerGlobal = defaultOpts.registerGlobal,
    } = {},
  ) {
    super();
    this._func = func;
    this.state = breakerState.CLOSED;

    this.failureThreshold = failureThreshold;
    this.successThreshold = successThreshold;

    this.timeout = timeout;

    this.name = name;
    this.group = group;

    this.failureCount = 0;
    this.successCount = 0;

    this.interval = interval;
    this.increment = increment;
    this.exponentInterval = exponentInterval;

    this.statsInterval = statsInterval;
    this.registerGlobal = registerGlobal;

    this.retryCount = 0;

    this.nextAttempt = Date.now();

    this.fallback = fallback;

    this.stats = new Stats({
      bucketSpan,
      bucketCount,
    });

    this.stats.startRolling();
    this.startStatsMonitor();
    this.registerToGlobal();
  }

  exec() {
    const execStart = Date.now();
    return new Promise((resolve, reject) => {
      const args = arguments;

      this.emit(events.EXEC);

      if (this.state === breakerState.OPEN) {
        //switch to half open if time interval passed
        const now = Date.now();

        if (now >= this.nextAttempt) {
          this.halfOpen();
        } else {
          this.stats.addShortCircuited();

          //immediately reject or fallingback when in backoff interval
          this.executeFallback(
            args,
            reject,
            new CircuitBrokenError('Circuit Broken'),
          );

          return;
        }
      }

      let executionCaptured = false; //flag to prevent bucket to record double stats from timeout and execution

      //create timeout timer, reject with timeout error if execution timeout
      const timeoutTimer = setTimeout(() => {
        if (executionCaptured) return;

        const err = new TimeoutError('Service Timeout');

        this.stats.addTimeOut();
        this.emit(events.TIMEOUT, err);
        this.failure(Date.now() - execStart, err);
        executionCaptured = true;

        this.executeFallback(args, reject, err);
      }, this.timeout);

      //attempt to execute service
      this._func
        .apply(null, args)
        .then((result) => {
          if (executionCaptured) return;

          clearTimeout(timeoutTimer);

          this.success(Date.now() - execStart);
          executionCaptured = true;

          resolve(result);
        })
        .catch((err) => {
          if (executionCaptured) return;

          clearTimeout(timeoutTimer);
          let passedError = null;

          if (!(err instanceof NonBreakingError)) {
            this.failure(Date.now() - execStart, err);
            passedError = err;
          } else {
            this.success(Date.now() - execStart);
            passedError = err.error;
          }

          executionCaptured = true;

          this.executeFallback(args, reject, passedError);
        })
        .catch((err) => {
          if (executionCaptured) return;

          let passedError = null;
          if (!(err instanceof NonBreakingError)) {
            this.failure(Date.now() - execStart, err);
            passedError = err;
          } else {
            this.success(Date.now() - execStart);
            passedError = err.error;
          }

          reject(passedError);
        });

      timeoutTimer.unref();
    });
  }

  static getGlobalStats() {
    return globalStats;
  }

  registerToGlobal() {
    if (this.registerGlobal) globalStats.registerBreaker(this);
  }

  startStatsMonitor() {
    if (this.statsMonitorInterval) clearInterval(this.statsMonitorInterval);

    this.statsMonitorInterval = setInterval(() => {
      this.emit(events.STATS, {
        name: this.name,
        group: this.group,
        state: this.state,
        failureThreshold: this.failureThreshold,
        successThreshold: this.successThreshold,
        nextAttempt: this.nextAttempt,
        retryCount: this.retryCount,
        bucketSpan: this.stats?.bucketSpan,
        bucketCount: this.stats?.bucketCount,
        increment: this.increment,
        exponentInterval: this.exponentInterval,
        interval: this.interval,
        timeout: this.timeout,
        stats: {
          ...this.stats?.latestStats,
          avgSuccess: this.stats?.getAvgSuccess(),
          avgFailure: this.stats?.getAvgFailure(),
        },
      });
    }, this.statsInterval);

    this.statsMonitorInterval.unref();
  }

  executeFallback(args, reject, defaultError) {
    //check if fallback function exists
    if (typeof this.fallback === 'function') {
      this.fallback
        .apply(null, args)
        .then((result) => {
          reject(result);
        })
        .catch((err) => {
          reject(err);
        });
    } else {
      reject(defaultError);
    }
  }

  success(runTime) {
    this.emit(events.SUCCESS);
    this.failureCount = 0;
    this.stats.addSuccess(runTime);
    if (this.state === breakerState.HALF_OPEN) {
      this.successCount++; //increment successcount when half open

      //close circuit when success threshold passed
      if (this.stats.getAvgSuccess() >= this.successThreshold) {
        this.close();

        this.successCount = 0;
        this.failureCount = 0;
      }
    }
  }

  failure(runTime, err) {
    this.emit(events.FAILURE, err);
    this.failureCount++;
    this.stats.addFailed(runTime);
    if (this.stats.getAvgFailure() >= this.failureThreshold) {
      this.open();

      const now = Date.now();

      let addedNextattempt = this.interval; //default interval = fixed interval

      //check for increment interval
      if (this.increment > 0) {
        addedNextattempt = (this.retryCount + 1) * this.increment;
      }

      //check for exponential interval
      if (this.exponentInterval) {
        //validate interval is not less than 1s for exponential. if so, interval will be set to 2s after 1st try
        const interval =
          this.retryCount == 0 ? this.interval : Math.max(this.interval, 2000);

        addedNextattempt =
          Math.pow(interval / 1000, this.retryCount + 1) * 1000;
      }

      this.nextAttempt = now + addedNextattempt;
      this.failureCount = 0;
    }
  }

  open() {
    this.state = breakerState.OPEN;
    this.failureCount = 0;
    this.successCount = 0;
    this.emit(events.OPEN);
  }

  close() {
    this.state = breakerState.CLOSED;
    this.failureCount = 0;
    this.successCount = 0;
    this.retryCount = 0;
    this.emit(events.CLOSED);
  }

  halfOpen() {
    this.state = breakerState.HALF_OPEN;
    this.failureCount = 0;
    this.successCount = 0;
    this.retryCount += 1;
    this.emit(events.HALF_OPEN);
  }

  static create(service, name = defaultOpts.name, group = defaultOpts.group) {
    return new Brakes(service, { name, group });
  }

  withFailureThreshold(threshold) {
    this.failureThreshold = threshold;
    return this;
  }

  withSuccessThreshold(threshold) {
    this.successThreshold = threshold;
    return this;
  }

  withFallbackService(service) {
    this.fallback = service;
    return this;
  }

  withBucket({
    bucketSpan = defaultOpts.bucketSpan,
    bucketCount = defaultOpts.bucketCount,
  }) {
    this.stats = new Stats({
      bucketSpan,
      bucketCount,
    });

    this.stats.startRolling();
    return this;
  }

  withBackoffInterval({
    interval = defaultOpts.interval,
    increment = defaultOpts.increment,
    exponential = defaultOpts.exponentInterval,
  } = {}) {
    this.interval = interval;
    this.increment = increment;
    this.exponentInterval = exponential;

    return this;
  }

  withExecutionTimeout(timeout = defaultOpts.timeout) {
    this.timeout = timeout;

    return this;
  }

  withStatsInterval(interval) {
    this.statsInterval = interval;
    this.startStatsMonitor();
    return this;
  }
}

Brakes.NonBreakingError = NonBreakingError;

module.exports = Brakes;

